import json
inv = json.load(open('bench/results/2026-10-12/m1-ngram/recon/inventory.json'))
for r in inv['runs']:
    print(r['run_id'], list(r['steps'].keys()))
    for k, s in r['steps'].items():
        roles = {}
        for t in s['tap_records']:
            roles[t['role']] = roles.get(t['role'], 0) + 1
        print('  step', k, 'n_events', s.get('n_events'), 'tap roles', roles, 'n_assistant', s.get('n_assistant_messages'), 'tool_calls', s.get('tool_calls'))
" 2>&1 | head -60

