import json
ev = json.load(open('bench/results/2026-10-12/m1-ngram/recon/event_samples.json'))
for k, v in ev['samples'].items():
    print('==', k, type(v).__name__, 'n:', len(v) if isinstance(v, list) else '')
    if isinstance(v, list):
        for i, item in enumerate(v[:3]):
            if isinstance(item, dict):
                keys = list(item.keys())
                print('  item', i, keys[:25])
                # show first-level values that are strings or lists
                for kk, vv in list(item.items())[:8]:
                    if isinstance(vv, str):
                        print('    ', kk, 'str', len(vv), vv[:120].replace('\n','\\n'))
                    elif isinstance(vv, dict):
                        print('    ', kk, 'dict', list(vv.keys())[:15])
                    elif isinstance(vv, list):
                        print('    ', kk, 'list', len(vv), vv[:2] if len(vv)<5 else str(vv[0])[:120])
EOF

